package com.bank.validator.service;

import com.bank.validator.dto.ValidationRequest;
import com.bank.validator.dto.ValidationResponse;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class TransactionValidatorService {

    private final EntityManager em;

    @Value("${validation.max-amount:1000000}")
    private BigDecimal maxAmount;

    @Value("${validation.min-balance:100}")
    private BigDecimal minBalance;

    // Track JVM startup time
    private static final long JVM_START_TIME = ProcessHandle.current().info().startInstant()
        .map(i -> i.toEpochMilli()).orElse(System.currentTimeMillis());

    @Transactional(readOnly = true)
    public ValidationResponse validate(ValidationRequest request) {
        long startMs = System.currentTimeMillis();
        List<String> errors = new ArrayList<>();

        // Rule 1: Amount must be positive and within limit
        if (request.amount() == null || request.amount().signum() <= 0) {
            errors.add("Amount must be positive");
        } else if (request.amount().compareTo(maxAmount) > 0) {
            errors.add("Amount exceeds maximum Rs." + maxAmount);
        }

        // Rule 2: From-account must exist and be active
        Object[] fromAccount = (Object[]) em.createNativeQuery(
            "SELECT balance, status FROM accounts WHERE account_id = ?1")
            .setParameter(1, request.fromAccount())
            .getResultStream().findFirst().orElse(null);

        if (fromAccount == null) {
            errors.add("Source account not found: " + request.fromAccount());
        } else {
            BigDecimal balance = (BigDecimal) fromAccount[0];
            String status = (String) fromAccount[1];

            if (!"ACTIVE".equals(status)) {
                errors.add("Source account is " + status + " — cannot transact");
            }
            if (request.amount() != null && balance.subtract(request.amount()).compareTo(minBalance) < 0) {
                errors.add("Insufficient balance: Rs." + balance + " - Rs." + request.amount()
                    + " would leave below minimum Rs." + minBalance);
            }
        }

        // Rule 3: To-account must exist
        Long toExists = (Long) em.createNativeQuery(
            "SELECT COUNT(*) FROM accounts WHERE account_id = ?1")
            .setParameter(1, request.toAccount())
            .getSingleResult();
        if (toExists == 0) {
            errors.add("Destination account not found: " + request.toAccount());
        }

        long validationTime = System.currentTimeMillis() - startMs;
        long jvmUptime = System.currentTimeMillis() - JVM_START_TIME;

        // Detect CDS usage
        String optimization = detectStartupOptimization();

        log.info("Validation completed in {}ms | JVM uptime: {}ms | CDS: {}",
            validationTime, jvmUptime, optimization);

        return new ValidationResponse(errors.isEmpty(), errors,
            validationTime, jvmUptime, optimization);
    }

    private String detectStartupOptimization() {
        // Check if CDS is active by examining JVM flags
        boolean cdsEnabled = java.lang.management.ManagementFactory.getRuntimeMXBean()
            .getInputArguments().stream()
            .anyMatch(arg -> arg.contains("SharedArchiveFile") || arg.contains("Xshare:on"));
        return cdsEnabled ? "CDS ACTIVE — faster startup!" : "NO CDS — standard startup";
    }
}
