package com.bank.validator;

import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;

@SpringBootApplication
@Slf4j
public class ValidatorApplication {

    private static final long START_NANO = System.nanoTime();

    public static void main(String[] args) {
        SpringApplication.run(ValidatorApplication.class, args);
    }

    @EventListener(ApplicationReadyEvent.class)
    public void onReady() {
        long startupMs = (System.nanoTime() - START_NANO) / 1_000_000;
        log.info("═══════════════════════════════════════════════════");
        log.info("  STARTUP TIME: {} ms", startupMs);
        log.info("  Without CDS: ~2500-4000 ms (typical Spring Boot)");
        log.info("  With CDS:    ~1000-1500 ms (40% faster)");
        log.info("  With Leyden: ~100-200 ms (target — Project Leyden)");
        log.info("═══════════════════════════════════════════════════");
    }
}
