package com.bank.validator.service;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class StartupTimingTest {

    @Test
    void cdsConceptExplained() {
        // CDS: Class Data Sharing
        // 1. Training run: JVM loads all classes, dumps metadata to .jsa archive
        // 2. Production run: JVM memory-maps the .jsa → skip class parsing
        // Result: 20-40% faster startup

        // Leyden goes further:
        // - Pre-resolved constant pools (skip linking)
        // - Pre-verified bytecode (skip verification)
        // - AOT-compiled hot methods (skip JIT warm-up)
        // Result: 90%+ faster startup (sub-100ms for Spring Boot)

        assertThat(true).isTrue();  // conceptual test
    }

    @Test
    void serverlessColdStartImpact() {
        // AWS Lambda Spring Boot cold start timings:
        // No optimization:      4000-8000 ms
        // With CDS:            1500-3000 ms
        // With Leyden (target): 100-500 ms
        // With GraalVM native:  50-200 ms (but limited reflection support)

        // Leyden advantage over GraalVM native:
        // - Full JVM features (reflection, proxies, dynamic class loading)
        // - No closed-world constraint
        // - Standard JDK (no separate toolchain)
        // - Compatible with all Spring Boot features

        long typicalColdStart = 4000;
        long withCDS = 1500;
        long withLeyden = 200;

        assertThat(withCDS).isLessThan(typicalColdStart);
        assertThat(withLeyden).isLessThan(withCDS);
    }
}
